import type { DocumentType } from "@tfm/contracts";
import type { Db, ObjectId } from "mongodb";
import type { DocumentMimeType } from "./file-type.js";

// The BSON shape. The id is generated by the service so the S3 key can be built before the insert.
export interface DocumentDoc {
  _id: ObjectId;
  type: DocumentType;
  name: string;
  version: string;
  fileName: string;
  s3Key: string;
  mimeType: DocumentMimeType;
  size: number;
  createdAt: Date;
}

export interface DocumentsRepository {
  insert(doc: DocumentDoc): Promise<DocumentDoc>;
}

export function createDocumentsRepository(db: Db): DocumentsRepository {
  const documents = db.collection<DocumentDoc>("documents");

  return {
    async insert(doc) {
      await documents.insertOne({ ...doc });
      return doc;
    },
  };
}
